mapper.select:
select t.txn_id, t.member_id, t.txn_type, t.amount, t.fee, t.balance_after, t.counterparty_id, t.biz_key, t.remark, t.create_time, c.nickname as counterparty_name from hys_wallet_txn t left join hys_member c on c.member_id = t.counterparty_id
and t.member_id = #{memberId} and t.txn_type = #{txnType}
and t.txn_type in #{tp}
and t.amount > 0 and t.amount < 0
order by t.txn_id desc

select coalesce(sum(abs(amount)), 0) from hys_wallet_txn
where member_id = #{memberId}
  and txn_type in
  #{tp}

    and amount > 0
    and amount < 0
